-- ============================================================================
-- journey page text (static blocks) — 2026-09-13  ·  DB: chhath-core
--
-- RUN THIS FILE AGAINST **chhath-core** ONLY:
--   wrangler d1 execute chhath-core --remote --file=./migration/2026-09-05/29-journey-page-text.sql
--
-- Test locally first (safe, hits the local replica):
--   wrangler d1 execute chhath-core --local --file=./migration/2026-09-05/29-journey-page-text.sql
--
-- Makes ALL the remaining static prose on the public "Our Journey" (Decade) page
-- editable from the mgmt "Journey Content" tab — intro, origin, portal callout,
-- transparency-evolution timeline (5 steps), "Our Thinking" + 3 milestones,
-- closing, footer, plus the table/label strings and the current-year note.
--
-- Stored as TWO key/value rows in the existing portal_settings table — one JSON
-- blob per language:
--   journey_page_text_en   {"intro":"...","origin_h":"...", ... }
--   journey_page_text_hi   {"intro":"...","origin_h":"...", ... }
-- (Year cards + tagline stay in journey_entries / journey_tagline_* from
-- migration 28; those are unchanged.)
--
-- Some values keep {placeholders} (e.g. {start}/{end}/{amount}/{count}/{year}) —
-- the frontend interpolates them exactly like the i18n strings did.
--
-- The seed below carries the EXACT current text (en + hi), so the page looks
-- identical and future edits happen in the DB, never in code. Idempotent: each
-- INSERT is guarded by WHERE NOT EXISTS, so a second run adds nothing.
-- ============================================================================

INSERT INTO portal_settings ("key", value)
SELECT 'journey_page_text_en', '{"intro":"A decade-long journey of faith, participation and transparency. Rooted in the tradition of an ancient festival, a youth-led organised effort began in 2017 — and over the years it grew into more than an event: a journey of collective participation, responsibility, trust and transparency.","origin_h":"Where did our journey begin?","origin_p1":"Chhath Puja is an ancient and widely observed Hindu festival tied to devotion, sun worship, fasting, purity, discipline, gratitude toward nature and collective participation. In our village too, the tradition of Chhath Puja existed long before 2017.","origin_p2":"At one time, the ghat and its surroundings were decorated and special arrangements were made during Chhath. Back then a few prominent people of the village played a key role, and their involvement gave the event a special level of collective organisation.","origin_p3":"In time, when those prominent people stepped away, the tradition of Chhath Puja continued, but the earlier decoration and collective arrangements faded. The puja carried on, though the event became relatively modest.","origin_p4":"This was the backdrop from which the need for a fresh initiative was felt.","journey_h":"Our Journey","evolution_line":"Paper → PDF → WhatsApp → Google Sheets → Transparency Portal","portal_h":"Chhath Puja Transparency Portal","portal_p":"In 2026 this years-old tradition of transparency is being brought to a dedicated digital platform.","current_note_h":"The {year} financial records are not final yet","current_note_p":"It should be clearly recorded that Chhath {year} is not yet complete. So the {year} figures are not presented as final historical data. The actual {year} contribution records are updated live during the year and finalised after Chhath. This keeps a clear distinction between historical and current information.","table_h":"{start} → {end} — Our Financial Journey","th_year":"Year","th_total":"Total Contribution","th_contributors":"Contributors","total_label":"Total Contribution","contributors_label":"Contributors","totals_h":"Total recorded figures, {start} → {end}","total_amount":"{amount} — total recorded contribution","total_entries":"{count} — year-wise recorded contributor entries","total_clarify":"{count} should not be read as the number of unique individuals. The same person may contribute in different years, so {count} is the year-wise total of all recorded contributor entries — not {count} separate people.","timeline_h":"Our Journey of Transparency","tl_paper_h":"First — Paper Records","tl_paper_d":"In the early years the income–expense accounts were prepared on paper. The original record of financial information was paper-based.","tl_pdf_h":"Then — PDF Records","tl_pdf_d":"The paper account pages were turned into PDFs, making it possible to share records in a digital format.","tl_wa_h":"Then — WhatsApp Group","tl_wa_d":"PDF records were shared with the community through a WhatsApp group, so financial information reached group members.","tl_sheets_h":"From 2021 — Google Sheets","tl_sheets_d":"In 2021 the 2017–2021 records were organised into a Google Sheet and made public via a view-only URL, giving records a more structured, accessible digital form.","tl_portal_h":"2026 — Transparency Portal","tl_portal_d":"Now the same journey of transparency has reached a dedicated digital platform.","think_h":"Our Thinking","think_lead":"Transparency is not a new feature — it is our responsibility.","think_p":"From 2017 the journey moved forward. The medium of records changed, technology changed, community participation grew — but the idea of transparency stayed.","ms_2017_h":"2017 — A New Organised Beginning","ms_2017_d":"The youth began organising the event with new energy and better arrangements.","ms_2021_h":"2021 — Digital Transparency","ms_2021_d":"The existing transparency practice took digital form via Google Sheets and view-only public access.","ms_2026_h":"2026 — 10th Year • Transparency Portal","ms_2026_d":"In the tenth year the same journey of transparency reached a dedicated digital platform.","closing_h":"Faith • Unity • Transparency","closing_p1":"The tradition of an ancient festival. The initiative of a new generation. A ten-year collective journey. And transparency held from the very start.","closing_p2":"This is not just a count of years — it is the story of a continuous effort in which tradition endured, a new generation took responsibility, community participation grew, and the medium of transparency evolved with time.","closing_p3":"The medium is more digital than ever, but the purpose is the same — keep trust, carry the community along, and keep advancing transparency.","footer":"Same tradition, a new medium — the journey of transparency continues."}'
WHERE NOT EXISTS (SELECT 1 FROM portal_settings WHERE "key" = 'journey_page_text_en');

INSERT INTO portal_settings ("key", value)
SELECT 'journey_page_text_hi', '{"intro":"आस्था, सहभागिता और पारदर्शिता की एक दशक लंबी यात्रा। एक प्राचीन पर्व की परंपरा में जड़ें रखते हुए, 2017 में युवाओं के नेतृत्व में एक संगठित प्रयास शुरू हुआ — और वर्षों में यह एक आयोजन से बढ़कर बन गया: सामूहिक सहभागिता, जिम्मेदारी, विश्वास और पारदर्शिता की एक यात्रा।","origin_h":"हमारी यात्रा कहाँ से शुरू हुई?","origin_p1":"छठ पूजा एक प्राचीन और व्यापक रूप से मनाया जाने वाला हिंदू पर्व है, जो श्रद्धा, सूर्य उपासना, व्रत, शुद्धता, अनुशासन, प्रकृति के प्रति कृतज्ञता और सामूहिक सहभागिता से जुड़ा है। हमारे गाँव में भी छठ पूजा की परंपरा 2017 से बहुत पहले से मौजूद थी।","origin_p2":"एक समय था जब छठ के दौरान घाट और उसके आस-पास सजावट होती थी और विशेष व्यवस्थाएँ की जाती थीं। तब गाँव के कुछ प्रमुख लोग महत्वपूर्ण भूमिका निभाते थे, और उनकी भागीदारी से आयोजन को सामूहिक संगठन का एक विशेष स्तर मिलता था।","origin_p3":"समय के साथ, जब वे प्रमुख लोग पीछे हट गए, तो छठ पूजा की परंपरा जारी रही, पर पहले जैसी सजावट और सामूहिक व्यवस्थाएँ फीकी पड़ गईं। पूजा चलती रही, हालाँकि आयोजन अपेक्षाकृत साधारण हो गया।","origin_p4":"यही वह पृष्ठभूमि थी, जहाँ से एक नई पहल की आवश्यकता महसूस हुई।","journey_h":"हमारी यात्रा","evolution_line":"Paper → PDF → WhatsApp → Google Sheets → Transparency Portal","portal_h":"Chhath Puja Transparency Portal","portal_p":"2026 में इसी पारदर्शिता की वर्षों पुरानी परंपरा को एक dedicated digital platform तक पहुँचाया जा रहा है।","current_note_h":"{year} के financial records अभी final नहीं हैं","current_note_p":"यह स्पष्ट रूप से दर्ज किया जाना चाहिए कि Chhath {year} अभी पूरा नहीं हुआ है। इसलिए {year} के financial figures को final historical data के रूप में प्रस्तुत नहीं किया जा रहा है। {year} के वास्तविक contribution records वर्ष के दौरान live update किए जाते हैं और Chhath के बाद final किए जाते हैं। इससे historical तथा current information के बीच स्पष्ट अंतर बना रहता है।","table_h":"{start} → {end} — हमारी Financial Journey","th_year":"वर्ष","th_total":"कुल योगदान","th_contributors":"Contributors","total_label":"कुल योगदान","contributors_label":"Contributors","totals_h":"{start} → {end} के कुल recorded figures","total_amount":"{amount} — कुल recorded contribution","total_entries":"{count} — Year-wise recorded contributor entries","total_clarify":"{count} को unique individuals की संख्या नहीं कहा जाना चाहिए। एक ही व्यक्ति अलग-अलग वर्षों में योगदान कर सकता है, इसलिए {count} का अर्थ है सभी वर्षों के recorded contributor entries का year-wise total, न कि {count} अलग-अलग व्यक्ति।","timeline_h":"Transparency की हमारी यात्रा","tl_paper_h":"पहले — Paper Records","tl_paper_d":"शुरुआती वर्षों में आय-व्यय का हिसाब कागज़ पर तैयार किया जाता था। financial information का मूल record paper-based था।","tl_pdf_h":"फिर — PDF Records","tl_pdf_d":"कागज़ के हिसाब पन्नों को PDF में बदला गया, जिससे records को digital रूप में साझा करना संभव हुआ।","tl_wa_h":"फिर — WhatsApp Group","tl_wa_d":"PDF records को WhatsApp group के माध्यम से community के साथ साझा किया गया, ताकि financial information group members तक पहुँचे।","tl_sheets_h":"2021 से — Google Sheets","tl_sheets_d":"2021 में 2017–2021 के records को Google Sheet में व्यवस्थित किया गया और view-only URL से public किया गया, जिससे records को अधिक संरचित, सुलभ digital रूप मिला।","tl_portal_h":"2026 — Transparency Portal","tl_portal_d":"अब वही पारदर्शिता की यात्रा एक dedicated digital platform तक पहुँच गई है।","think_h":"हमारी सोच","think_lead":"Transparency कोई नई feature नहीं — यह हमारी जिम्मेदारी है।","think_p":"2017 से यात्रा आगे बढ़ी। records का माध्यम बदला, तकनीक बदली, community participation बढ़ी — पर पारदर्शिता की सोच वही रही।","ms_2017_h":"2017 — एक नई संगठित शुरुआत","ms_2017_d":"युवाओं ने नए उत्साह और बेहतर व्यवस्था के साथ आयोजन को संगठित करना शुरू किया।","ms_2021_h":"2021 — Digital पारदर्शिता","ms_2021_d":"मौजूदा पारदर्शिता व्यवस्था ने Google Sheets और view-only public access के माध्यम से digital रूप लिया।","ms_2026_h":"2026 — 10वाँ वर्ष • Transparency Portal","ms_2026_d":"दसवें वर्ष में वही पारदर्शिता की यात्रा एक dedicated digital platform तक पहुँची।","closing_h":"आस्था • एकता • पारदर्शिता","closing_p1":"एक प्राचीन पर्व की परंपरा। एक नई पीढ़ी की पहल। दस वर्षों की सामूहिक यात्रा। और शुरुआत से बनी हुई पारदर्शिता।","closing_p2":"यह केवल वर्षों की गिनती नहीं — यह एक निरंतर प्रयास की कहानी है जिसमें परंपरा टिकी रही, एक नई पीढ़ी ने जिम्मेदारी ली, community participation बढ़ी, और पारदर्शिता का माध्यम समय के साथ विकसित हुआ।","closing_p3":"माध्यम पहले से कहीं अधिक digital है, पर उद्देश्य वही है — विश्वास बनाए रखना, community को साथ लेकर चलना, और पारदर्शिता को आगे बढ़ाते रहना।","footer":"वही परंपरा, एक नया माध्यम — पारदर्शिता की यात्रा जारी है।"}'
WHERE NOT EXISTS (SELECT 1 FROM portal_settings WHERE "key" = 'journey_page_text_hi');
